// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

function normalizeDbConnString(raw: string) {
  let u: URL;
  try {
    u = new URL(raw);
  } catch {
    return raw;
  }

  const host = u.hostname.toLowerCase();
  const isSupabase = host.includes("supabase.co") || host.includes("supabase.com");
  const sslmode = (u.searchParams.get("sslmode") ?? "").toLowerCase();
  const shouldApplyCompat =
    isSupabase && (sslmode === "require" || sslmode === "prefer" || sslmode === "verify-ca");

  if (shouldApplyCompat && !u.searchParams.has("uselibpqcompat")) {
    u.searchParams.set("uselibpqcompat", "true");
  }

  return u.toString();
}

const useNetlifyDatabase = process.env["DATABASE_PROVIDER"] === "netlify";
const migrationDbUrl = useNetlifyDatabase
  ? process.env["NETLIFY_DB_URL"]
  : process.env["DATABASE_URL"] ??
    process.env["POSTGRES_URL_NON_POOLING"] ??
    process.env["POSTGRES_URL"];

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  // `prisma generate` only needs the schema. Netlify Database supplies its
  // connection string to deployed runtime code, not every build command.
  // Keep the datasource absent until a migration/introspection command gets a
  // real URL, so production builds do not fail before Next.js starts.
  ...(migrationDbUrl
    ? {
        datasource: {
          url: normalizeDbConnString(migrationDbUrl),
        },
      }
    : {}),
});
